INSERT INTO truss.request_receipt_route_guard AS g (namespace_sha256, request_sha256, generation) VALUES ($1::bytea, $2::bytea, 0) ON CONFLICT (namespace_sha256, request_sha256) DO UPDATE SET generation = g.generation RETURNING generation; SELECT r.storage_row_id, r.original_writer_xid::text, octet_length(r.original_writer_context_bytes) AS writer_context_bytes, r.expiry_writer_xid::text, octet_length(r.expiry_writer_context_bytes) AS expiry_writer_context_bytes, r.lifecycle_generation, r.payload_state, octet_length(r.namespace_identity_utf8) AS namespace_bytes, octet_length(r.request_id_utf8) AS request_bytes, octet_length(r.original_receipt_bytes) AS receipt_bytes, octet_length(r.expired_identity_bytes) AS expiry_bytes, p.protection_generation, p.original_update_writer_xid::text, octet_length(p.original_update_writer_context_bytes) AS protection_writer_context_bytes, octet_length(p.original_protection_bytes) AS protection_bytes, octet_length(p.original_update_evidence_bytes) AS update_evidence_bytes FROM truss.request_receipt r LEFT JOIN truss.request_receipt_protection p ON p.receipt_storage_row_id = r.storage_row_id WHERE r.namespace_sha256 = $1::bytea AND r.request_sha256 = $2::bytea ORDER BY r.storage_row_id LIMIT 10001; SELECT r.storage_row_id, r.namespace_identity_utf8, r.request_id_utf8 FROM truss.request_receipt r WHERE r.namespace_sha256 = $1::bytea AND r.request_sha256 = $2::bytea AND r.storage_row_id = ANY($3::bigint[]) ORDER BY r.storage_row_id; SELECT r.storage_row_id, r.original_writer_xid::text, r.original_writer_context_bytes, r.expiry_writer_xid::text, r.expiry_writer_context_bytes, r.lifecycle_generation, r.payload_state, r.original_receipt_bytes, r.expired_identity_bytes, p.protection_generation, p.original_update_writer_xid::text, p.original_update_writer_context_bytes, p.original_protection_bytes, p.original_update_evidence_bytes FROM truss.request_receipt r LEFT JOIN truss.request_receipt_protection p ON p.receipt_storage_row_id = r.storage_row_id WHERE r.namespace_sha256 = $1::bytea AND r.request_sha256 = $2::bytea AND r.storage_row_id = $3::bigint; UPDATE truss.request_receipt_route_guard SET generation = generation + 1 WHERE namespace_sha256 = $1::bytea AND request_sha256 = $2::bytea AND generation = $3::bigint AND generation < 9223372036854775807 RETURNING generation; UPDATE truss.request_receipt_route_guard SET generation = generation WHERE namespace_sha256 = $1::bytea AND request_sha256 = $2::bytea RETURNING generation; SELECT pg_catalog.pg_current_xact_id_if_assigned()::text AS observing_xid, pg_catalog.current_setting('transaction_read_only') AS transaction_read_only, pg_catalog.current_setting('transaction_isolation') AS transaction_isolation